run_px4.sh:
if router:
    gcs = "mavlink start -x -u $udp_gcs_port_local -r 4000000 -f"
    if mavlink_lines.count(gcs) != 1: sys.exit("Unsupported PX4 GCS startup layout.")
    mavlink_lines = [line + " -o ${XOVIUM_ROUTER_PX4_PORT:-14550}" if line == gcs else line for line in mavlink_lines]
Path(mavlink_path).write_text("\n".join(mavlink_lines) + "\n")
